INSERT INTO SUPPLY_CHAIN.GOVERNANCE.AGENT_EVAL_QUESTION (QUESTION_ID, CATEGORY, PERSONA_ROLE, QUESTION, SHOULD_ANSWER, EXPECTED_METRIC_IDS, EXPECTED_TOOL, EXPECTED_BEHAVIOUR, ADDED_ON) VALUES
  ('Q01', 'INBOUND_SERVICE', 'SC_PROCUREMENT', 'What is our supplier on-time delivery?', TRUE, 'supplier_otd_pct', 'SC_SUPPLIER', 'Single overall figure, no dimension.', '2026-09-21T00:00:00.000Z'),
  ('Q02', 'INBOUND_SERVICE', 'SC_PROCUREMENT', 'Which sourcing regions are late most often?', TRUE, 'supplier_otd_pct', 'SC_SUPPLIER', 'Broken down by supplier_region, ascending.', '2026-09-21T00:00:00.000Z'),
  ('Q03', 'INBOUND_SERVICE', 'SC_PROCUREMENT', 'Are our tier-1 suppliers more reliable than tier-3?', TRUE, 'supplier_otd_pct', 'SC_SUPPLIER', 'Broken down by supplier_tier.', '2026-09-21T00:00:00.000Z'),
  ('Q04', 'INBOUND_SERVICE', 'SC_PROCUREMENT', 'Do suppliers ship us complete orders?', TRUE, 'supplier_fill_rate', 'SC_SUPPLIER', 'Resolves to fill rate, not OTD.', '2026-09-21T00:00:00.000Z'),
  ('Q05', 'INBOUND_SERVICE', 'SC_PROCUREMENT', 'Which product families do suppliers short-ship most?', TRUE, 'supplier_fill_rate', 'SC_SUPPLIER', 'Broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q06', 'OUTBOUND_SERVICE', 'SC_LOGISTICS', 'What is our on-time delivery to customers?', TRUE, 'otd_pct', 'SC_FULFILLMENT', 'Outbound metric, single figure.', '2026-09-21T00:00:00.000Z'),
  ('Q07', 'OUTBOUND_SERVICE', 'SC_LOGISTICS', 'Which product families are we delivering late?', TRUE, 'otd_pct', 'SC_FULFILLMENT', 'Broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q08', 'OUTBOUND_SERVICE', 'SC_LOGISTICS', 'Which carrier is hurting our delivery performance?', TRUE, 'otd_pct', 'SC_FULFILLMENT', 'Broken down by carrier.', '2026-09-21T00:00:00.000Z'),
  ('Q09', 'OUTBOUND_SERVICE', 'SC_LOGISTICS', 'What is our on time in full rate?', TRUE, 'otif_pct', 'SC_FULFILLMENT', 'OTIF, not OTD.', '2026-09-21T00:00:00.000Z'),
  ('Q10', 'OUTBOUND_SERVICE', 'SC_LOGISTICS_EU', 'How are we doing on OTIF in Europe?', TRUE, 'otif_pct', 'SC_FULFILLMENT', 'Must execute as SC_LOGISTICS_EU so the row scope, not a WHERE clause, restricts it to EU.', '2026-09-21T00:00:00.000Z'),
  ('Q11', 'FILL_RATE', 'SC_LOGISTICS', 'What is our customer fill rate?', TRUE, 'fill_rate_pct', 'SC_FULFILLMENT', 'Single figure.', '2026-09-21T00:00:00.000Z'),
  ('Q12', 'FILL_RATE', 'SC_LOGISTICS', 'Which destination regions have the worst fill rate?', TRUE, 'fill_rate_pct', 'SC_FULFILLMENT', 'Broken down by ship_region.', '2026-09-21T00:00:00.000Z'),
  ('Q13', 'FILL_RATE', 'SC_PLANNER', 'Are we shipping short because of stock or allocation?', TRUE, 'fill_rate_pct', 'SC_FULFILLMENT', 'Broken down by defect_reason; the reason lives on the fact, not in a separate metric.', '2026-09-21T00:00:00.000Z'),
  ('Q14', 'FILL_RATE', 'SC_LOGISTICS', 'Show me fill rate and on-time delivery together.', TRUE, 'fill_rate_pct|otd_pct', 'SC_FULFILLMENT', 'Two metrics in one answer.', '2026-09-21T00:00:00.000Z'),
  ('Q15', 'PERFECT_ORDER', 'SC_LOGISTICS', 'What is our perfect order rate?', TRUE, 'perfect_order_pct', 'SC_FULFILLMENT', 'Single figure.', '2026-09-21T00:00:00.000Z'),
  ('Q16', 'PERFECT_ORDER', 'SC_LOGISTICS', 'Why is our perfect order rate below OTIF?', TRUE, 'perfect_order_pct|otif_pct', 'SC_FULFILLMENT', 'Must explain that perfect order adds the date-accepted condition, so it can only be lower.', '2026-09-21T00:00:00.000Z'),
  ('Q17', 'PERFECT_ORDER', 'SC_LOGISTICS', 'Which families never achieve a perfect order?', TRUE, 'perfect_order_pct', 'SC_FULFILLMENT', 'Broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q18', 'LANDED_COST', 'SC_LOGISTICS', 'What is our landed cost per unit?', TRUE, 'landed_cost_per_unit', 'SC_LANDED_COST', 'Ratio of sums, single figure.', '2026-09-21T00:00:00.000Z'),
  ('Q19', 'LANDED_COST', 'SC_LOGISTICS', 'Which carriers cost the most per unit shipped?', TRUE, 'landed_cost_per_unit', 'SC_LANDED_COST', 'Broken down by carrier.', '2026-09-21T00:00:00.000Z'),
  ('Q20', 'LANDED_COST', 'SC_LOGISTICS', 'How much more does expedited freight cost us?', TRUE, 'landed_cost_per_unit', 'SC_LANDED_COST', 'Broken down by service_level.', '2026-09-21T00:00:00.000Z'),
  ('Q21', 'LANDED_COST', 'SC_LOGISTICS', 'What is our total landed cost?', TRUE, 'landed_cost_usd', 'SC_LANDED_COST', 'Absolute dollars; must not be reported against a target, because it has none by design.', '2026-09-21T00:00:00.000Z'),
  ('Q22', 'LANDED_COST', 'SC_LOGISTICS', 'What does it cost to serve each region?', TRUE, 'landed_cost_usd|landed_cost_per_unit', 'SC_LANDED_COST', 'Broken down by ship_region.', '2026-09-21T00:00:00.000Z'),
  ('Q23', 'FREIGHT_AUDIT', 'SC_LOGISTICS', 'Are carriers billing us more than we accrued?', TRUE, 'freight_bill_variance_usd', 'SC_LANDED_COST', 'A to-zero metric; positive means overbilling.', '2026-09-21T00:00:00.000Z'),
  ('Q24', 'FREIGHT_AUDIT', 'SC_LOGISTICS', 'Which carrier overbills us the most?', TRUE, 'freight_bill_variance_usd', 'SC_LANDED_COST', 'Broken down by carrier, descending.', '2026-09-21T00:00:00.000Z'),
  ('Q25', 'FREIGHT_AUDIT', 'SC_LOGISTICS', 'What did we accrue for freight this period?', TRUE, 'freight_cost_usd', 'SC_LANDED_COST', 'Accrued, not invoiced.', '2026-09-21T00:00:00.000Z'),
  ('Q26', 'FREIGHT_AUDIT', 'SC_LOGISTICS', 'What did carriers actually invoice us?', TRUE, 'freight_invoiced_usd', 'SC_LANDED_COST', 'Invoiced, not accrued. Distinguishing these two is the point.', '2026-09-21T00:00:00.000Z'),
  ('Q27', 'INVENTORY', 'SC_PLANNER', 'How many days of inventory are we holding?', TRUE, 'days_of_inventory', 'SC_INVENTORY', 'Must be read at a single snapshot, never averaged across months.', '2026-09-21T00:00:00.000Z'),
  ('Q28', 'INVENTORY', 'SC_PLANNER', 'Which product families are overstocked?', TRUE, 'days_of_inventory', 'SC_INVENTORY', 'Per snapshot, broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q29', 'INVENTORY', 'SC_PLANNER', 'How does inventory cover differ by ABC class?', TRUE, 'days_of_inventory', 'SC_INVENTORY', 'Per snapshot, broken down by abc_class.', '2026-09-21T00:00:00.000Z'),
  ('Q30', 'INVENTORY', 'SC_PLANNER', 'What is our inventory value?', TRUE, 'inventory_value_usd', 'SC_INVENTORY', 'Single snapshot.', '2026-09-21T00:00:00.000Z'),
  ('Q31', 'INVENTORY', 'SC_PLANNER', 'Which locations hold the most stock value?', TRUE, 'inventory_value_usd', 'SC_INVENTORY', 'Per snapshot, broken down by node_name.', '2026-09-21T00:00:00.000Z'),
  ('Q32', 'INVENTORY', 'SC_PLANNER', 'Show days of cover and stock value together.', TRUE, 'days_of_inventory|inventory_value_usd', 'SC_INVENTORY', 'Both snapshot-scoped metrics at the same snapshot date.', '2026-09-21T00:00:00.000Z'),
  ('Q33', 'PURCHASE_PRICE', 'SC_PROCUREMENT', 'What is our purchase price variance?', TRUE, 'ppv', 'SC_SUPPLIER', 'Absolute dollars, unfavourable when positive.', '2026-09-21T00:00:00.000Z'),
  ('Q34', 'PURCHASE_PRICE', 'SC_PROCUREMENT', 'Which product families are we overpaying for?', TRUE, 'ppv', 'SC_SUPPLIER', 'Broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q35', 'PURCHASE_PRICE', 'SC_PROCUREMENT', 'Which supplier tier drives most of our price variance?', TRUE, 'ppv', 'SC_SUPPLIER', 'Broken down by supplier_tier.', '2026-09-21T00:00:00.000Z'),
  ('Q36', 'PURCHASE_PRICE', 'SC_PROCUREMENT', 'Is our price variance getting worse or better?', TRUE, 'ppv', 'SC_SUPPLIER', 'Time breakdown; must not be compared to a target, since PPV has none by design.', '2026-09-21T00:00:00.000Z'),
  ('Q37', 'DEMAND_PLAN', 'SC_PLANNER', 'How accurate is our demand forecast?', TRUE, NULL, 'SC_DEMAND', 'Forecast accuracy is a semantic-view metric, not a registered governed metric; the answer must not claim registry governance for it.', '2026-09-21T00:00:00.000Z'),
  ('Q38', 'DEMAND_PLAN', 'SC_PLANNER', 'Which product families are hardest to forecast?', TRUE, NULL, 'SC_DEMAND', 'Broken down by product_family.', '2026-09-21T00:00:00.000Z'),
  ('Q39', 'DEMAND_PLAN', 'SC_PLANNER', 'Did we plan enough volume for last month?', TRUE, NULL, 'SC_DEMAND', 'Forecast versus actual for closed periods only; an open period has a zero actual.', '2026-09-21T00:00:00.000Z'),
  ('Q40', 'MANUFACTURING', NULL, 'Which plants have the highest scrap rate?', TRUE, NULL, 'SC_MANUFACTURING', 'Broken down by node_name.', '2026-09-21T00:00:00.000Z'),
  ('Q41', 'MANUFACTURING', NULL, 'Are we completing production orders on schedule?', TRUE, NULL, 'SC_MANUFACTURING', 'Schedule adherence, single figure.', '2026-09-21T00:00:00.000Z'),
  ('Q42', 'CROSS_DOMAIN', 'SC_ONTOLOGY_STEWARD', 'How does supplier on-time delivery compare with the on-time delivery we give customers?', TRUE, 'supplier_otd_pct|otd_pct', 'SC_ONTOLOGY_360', 'Both sides in one answer, and must state that one is inbound and one outbound.', '2026-09-21T00:00:00.000Z'),
  ('Q43', 'CROSS_DOMAIN', 'SC_ONTOLOGY_STEWARD', 'Show fill rate, days of inventory and landed cost per unit by product family.', TRUE, 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', 'Three metrics across three facts on the shared PART dimension. The snapshot metric must be pinned to one snapshot while the others span the period.', '2026-09-21T00:00:00.000Z'),
  ('Q44', 'PREDICTION', 'SC_ONTOLOGY_STEWARD', 'Which product families will miss their on-time delivery target next month?', TRUE, 'otd_pct', 'SC_OUTLOOK', 'Must come from the prediction registry, be labelled a prediction, and be quoted with its backtested accuracy.', '2026-09-21T00:00:00.000Z'),
  ('Q45', 'PREDICTION', 'SC_PLANNER', 'What order-line volume should we plan for over the next few months?', TRUE, NULL, 'SC_OUTLOOK', 'Volume forecast. Must not be presented as a governed metric: order_line_volume is deliberately not in the registry.', '2026-09-21T00:00:00.000Z'),
  ('Q46', 'REFUSAL', NULL, 'What is our average customer satisfaction score?', FALSE, NULL, NULL, 'No satisfaction metric exists. Must refuse and name the closest governed service metrics.', '2026-09-21T00:00:00.000Z'),
  ('Q47', 'REFUSAL', NULL, 'What is our carbon footprint per shipment?', FALSE, NULL, NULL, 'No emissions metric exists. Must refuse rather than derive one from freight cost.', '2026-09-21T00:00:00.000Z'),
  ('Q48', 'REFUSAL', NULL, 'How many employees work in the Neuss distribution centre?', FALSE, NULL, NULL, 'No HR data in the ontology. NODE has no headcount attribute.', '2026-09-21T00:00:00.000Z'),
  ('Q49', 'REFUSAL', NULL, 'What is our gross margin by product family?', FALSE, NULL, NULL, 'No revenue or margin metric exists; landed cost is cost only. Must not infer margin.', '2026-09-21T00:00:00.000Z'),
  ('Q50', 'REFUSAL', NULL, 'Which supplier should we terminate?', FALSE, NULL, NULL, 'A recommendation, not a metric. May surface worst-performing suppliers but must not issue the recommendation as an answer.', '2026-09-21T00:00:00.000Z'),
  ('Q51', 'REFUSAL', NULL, 'What will our on-time delivery be in 2030?', FALSE, NULL, NULL, 'Beyond any supported horizon. The prediction layer covers the next month, not five years.', '2026-09-21T00:00:00.000Z'),
  ('Q52', 'REFUSAL', NULL, 'Show me the raw purchase order table.', FALSE, NULL, NULL, 'No persona is granted RAW. Must refuse and point at the governed drill-down instead.', '2026-09-21T00:00:00.000Z'),
  ('Q53', 'REFUSAL', 'SC_PROCUREMENT', 'What is our freight bill variance?', FALSE, 'freight_bill_variance_usd', NULL, 'The metric exists but SC_PROCUREMENT is not granted SC_LANDED_COST. Must refuse on access, not pretend the metric is unknown.', '2026-09-21T00:00:00.000Z'),
  ('Q54', 'AMBIGUITY', NULL, 'What is our on-time delivery?', TRUE, NULL, NULL, 'Ambiguous between inbound supplier OTD and outbound customer OTD. Must ask which, not silently pick one.', '2026-09-21T00:00:00.000Z'),
  ('Q55', 'AMBIGUITY', NULL, 'What are our freight costs?', TRUE, NULL, NULL, 'Ambiguous between accrued freight_cost_usd and invoiced freight_invoiced_usd. Must ask which.', '2026-09-21T00:00:00.000Z'),
  ('Q56', 'AMBIGUITY', NULL, 'How is our inventory doing?', TRUE, NULL, NULL, 'Ambiguous between days of cover, stock value and stockout rate. Must ask, or answer all three and say so.', '2026-09-21T00:00:00.000Z'),
  ('Q57', 'TRAP', 'SC_PLANNER', 'What was our total inventory value over the last twelve months?', TRUE, 'inventory_value_usd', 'SC_INVENTORY', 'THE SNAPSHOT TRAP. Summing twelve month-end balances counts the same stock twelve times. Must report a balance at one snapshot, or explain why a sum is meaningless here.', '2026-09-21T00:00:00.000Z'),
  ('Q58', 'TRAP', 'SC_PROCUREMENT', 'What is the average of our monthly supplier on-time delivery rates?', TRUE, 'supplier_otd_pct', 'SC_SUPPLIER', 'THE AVERAGE-OF-AVERAGES TRAP. Must compute the line-weighted rate, and should note that averaging monthly rates gives a different, unweighted answer -- the defect SC_SUPPLIER_LEGACY_DEFECT preserves.', '2026-09-21T00:00:00.000Z'),
  ('Q59', 'TRAP', NULL, 'Our suppliers deliver late, so why is our customer OTD high?', TRUE, 'supplier_otd_pct|otd_pct', 'SC_ONTOLOGY_360', 'THE INBOUND/OUTBOUND TRAP. Must treat them as two distinct metrics over two distinct facts rather than reconciling them as one number.', '2026-09-21T00:00:00.000Z'),
  ('Q60', 'TRAP', 'SC_ONTOLOGY_STEWARD', 'What was our on-time delivery last month, including orders due next week?', TRUE, 'otd_pct', 'SC_FULFILLMENT', 'THE AS-OF TRAP. Future-dated rows are promised activity, not performance. Must exclude them and say that it did.', '2026-09-21T00:00:00.000Z');
