  ('2026-09-21T11:32:32.239Z', 'app', 'SC_LOGISTICS', 'Show fill rate, days of inventory and landed cost per unit by product family', 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', FALSE, NULL, 8435, FALSE, NULL),
  ('2026-09-21T11:32:37.652Z', 'app', 'SC_LOGISTICS', 'What is our average customer satisfaction score?', NULL, 'SC_ONTOLOGY_360', TRUE, 'No customer satisfaction score metric exists in the governed catalogue; the available customer-facing metrics measure delivery performance (fill rate, on-time delivery, OTIF, perfect order rate) but not satisfaction surveys or ratings.', 4451, FALSE, NULL),
