  ('2026-09-21T11:38:10.021Z', 'app', 'SC_LOGISTICS', 'and by supplier region?', 'supplier_otd_pct', 'SC_ONTOLOGY_360', FALSE, NULL, 9340, FALSE, NULL),
  ('2026-09-21T11:38:23.416Z', 'app', 'SC_LOGISTICS', 'Show fill rate, days of inventory and landed cost per unit by product family', 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', FALSE, NULL, 6249, FALSE, NULL),
  ('2026-09-21T11:38:28.414Z', 'app', 'SC_LOGISTICS', 'What is our average customer satisfaction score?', NULL, 'SC_ONTOLOGY_360', TRUE, 'Customer satisfaction score is not available in the governed metric catalogue; the catalogue contains delivery performance metrics (OTD, fill rate, OTIF, perfect order) but no direct satisfaction or survey-based metrics.', 4525, FALSE, NULL),
  ('2026-09-21T11:39:49.241Z', 'app', 'SC_PLANNER', 'What is our supplier on-time delivery?', 'supplier_otd_pct', 'SC_ONTOLOGY_360', FALSE, NULL, 8319, FALSE, NULL),
  ('2026-09-21T11:40:33.811Z', 'app', 'SC_PLANNER', 'Show fill rate, days of inventory and landed cost per unit by product family', 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', FALSE, NULL, 9691, FALSE, NULL),
  ('2026-09-21T11:48:24.944Z', 'app', 'SC_PLANNER', 'Show fill rate, days of inventory and landed cost per unit by product family', 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', FALSE, NULL, 12885, FALSE, NULL),
  ('2026-09-21T12:02:05.059Z', 'app', 'SC_LOGISTICS', 'What is our supplier on-time delivery?', 'supplier_otd_pct', 'SC_ONTOLOGY_360', FALSE, NULL, 11163, FALSE, NULL),
  ('2026-09-21T12:02:17.885Z', 'app', 'SC_LOGISTICS', 'and by supplier region?', 'supplier_otd_pct', 'SC_ONTOLOGY_360', FALSE, NULL, 5708, FALSE, NULL),
  ('2026-09-21T12:02:35.665Z', 'app', 'SC_LOGISTICS', 'Show fill rate, days of inventory and landed cost per unit by product family', 'fill_rate_pct|days_of_inventory|landed_cost_per_unit', 'SC_ONTOLOGY_360', FALSE, NULL, 9765, FALSE, NULL),
  ('2026-09-21T12:02:40.509Z', 'app', 'SC_LOGISTICS', 'What is our average customer satisfaction score?', NULL, 'SC_ONTOLOGY_360', TRUE, 'No customer satisfaction score metric exists in the governed catalogue; the available customer service metrics are fill_rate_pct, otd_pct, otif_pct, and perfect_order_pct.', 4247, FALSE, NULL),
  ('2026-09-21T12:05:56.328Z', 'app', 'SC_LOGISTICS_EU', 'What is our on-time delivery to customers?', 'otd_pct', 'SC_ONTOLOGY_360', FALSE, NULL, 7076, FALSE, NULL),
  ('2026-09-21T12:06:02.683Z', 'app', 'SC_LOGISTICS_EU', 'What is our average customer satisfaction score?', NULL, 'SC_ONTOLOGY_360', TRUE, 'No customer satisfaction score metric exists in the catalogue; the available metrics cover operational performance (fill rate, on-time delivery, perfect order) but not direct satisfaction measurement.', 4604, FALSE, NULL),
