  ('2026-09-21T12:15:26.336Z', 'app', 'SC_PLANNER', 'How does that compare to inventory cover?', 'supplier_otd_pct|otd_pct|days_of_inventory', 'SC_ONTOLOGY_360', FALSE, NULL, 9004, FALSE, NULL),
