  ('2026-09-21T12:50:26.390Z', 'app', 'SC_LOGISTICS', 'What is our average customer satisfaction score?', NULL, 'SC_ONTOLOGY_360', TRUE, 'No customer satisfaction score metric exists in the catalogue; the available metrics cover delivery performance (OTD, OTIF, perfect order rate) but not direct customer satisfaction surveys or scores.', 4865, FALSE, NULL),
  ('2026-09-21T12:50:52.764Z', 'app', 'SC_LOGISTICS', 'What is our Days of Inventory?', 'days_of_inventory', 'SC_ONTOLOGY_360', FALSE, NULL, 6834, FALSE, NULL),
  ('2026-09-21T12:51:09.930Z', 'app', 'SC_LOGISTICS', 'Break that down by product family', 'days_of_inventory', 'SC_ONTOLOGY_360', FALSE, NULL, 5557, FALSE, NULL),
