  ('2026-09-23T06:27:49.190Z', 'app', 'SC_PLANNER', 'Which are missing target?', NULL, 'SC_ONTOLOGY_360', TRUE, 'The question asks which metrics are missing target, but the catalogue contains no target or goal metrics to compare actual performance against.', 3991, FALSE, NULL),
  ('2026-09-24T05:26:25.254Z', 'app', 'SC_PLANNER', 'who is the pm of india', NULL, 'SC_ONTOLOGY_360', TRUE, 'This question asks about political leadership and is completely outside the scope of a supply-chain metric catalogue.', 7467, FALSE, NULL);
INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_BASELINE (METRIC_ID, SEMANTIC_VIEW, METRIC_REFERENCE, OBSERVED_VALUE, DEFINITION_SQL, ROOT_CAUSE, CAPTURED_AT, NOTE) VALUES
  ('supplier_otd_pct', 'SC_SUPPLIER', 'supplier_delivery.supplier_otd_pct', 0.875824, 'AVG(is_on_time) over CANONICAL.FCT_SUPPLIER_DELIVERY_LINE', 'Correct definition: averages the on-time flag across receipt lines, so every line carries equal weight.', '2026-09-21T10:31:49.210Z', 'This is the governed definition. Retained as the reference side of the comparison.'),
  ('supplier_otd_pct', 'SC_SUPPLIER_LEGACY_DEFECT', 'supplier.supplier_otd_pct', 0.882630664, 'AVG(otd_rate) over CANONICAL.V_SUPPLIER_OTD_BY_MONTH, where otd_rate is already AVG(is_on_time) per supplier per month', 'Average of averages: the monthly rate is averaged again without weighting by receipt lines, so a supplier with 3 lines in a month counts as much as one with 900.', '2026-09-21T10:31:49.210Z', 'Kept deployed on purpose as a negative control. Never fix it: it is the only proof the drift test can fail.');
INSERT INTO SUPPLY_CHAIN.GOVERNANCE.METRIC_DRIFT_NEGATIVE_CONTROL (RUN_AT, METRIC_ID, BUSINESS_NAME, CANONICAL_VALUE, MIN_VALUE, MAX_VALUE, VALUE_SPREAD, STATUS, DETAIL, PURPOSE) VALUES
  ('2026-09-21T10:31:50.813Z', 'supplier_otd_pct', 'Supplier On-Time Delivery', 0.875824, 0.875824, 0.882630664, 0.006806663974, 'FAIL', 'SC_SUPPLIER.supplier_otd_pct=0.875824 | SC_SUPPLIER_LEGACY_DEFECT.supplier.supplier_otd_pct=0.882630663974 | canonical=0.875824', 'Proves METRIC_DRIFT_TEST is capable of failing. Both views claim to report supplier on-time delivery over the same receipt lines; one weights by line and one averages monthly rates. A control that has only ever passed cannot be distinguished from a control that is not running.');
